import { NAV_AREA, PLUGIN_PAGE_AREA, Page, Table, useQuery } from '@gents/ux-sdk'
import { jsx } from 'react/jsx-runtime'

function Holdings({ ctx }) {
  const q = useQuery(ctx, 'archive_desk', 'list_holdings', { pages: 'all' })
  const rows = q.data?.results ?? []
  return jsx(Page, { title: 'My Holdings', children: jsx(Table, { columns: ['shelf', 'box', 'status'], rows, rowKey: 'box', empty: 'No holdings.' }) })
}

export default {
  id: 'my_holdings',
  name: 'My Holdings',
  register(ctx) {
    ctx.registerMany([
      { id: 'nav', area: NAV_AREA, data: { id: 'my_holdings:nav', label: 'My Holdings', icon: 'archive', to: { name: 'plugin', pluginId: 'my_holdings' }, placement: 'footer' } },
      { id: 'page', area: PLUGIN_PAGE_AREA, render: () => jsx(Holdings, { ctx }) },
    ])
  },
}

